            (, uint256 amount,) = AaveLendingPoolCoreV1.getUserBorrowBalances(address(usdt), aaveV1UsdtDebtUsers[i]);
            if (amount != 0) {
                uint256 repaymentAmount = amount * 101 / 100;
                LendingPool.repay(address(usdt), repaymentAmount, aaveV1UsdtDebtUsers[i]);
